"""Half-open integer interval utilities."""


def _clean(intervals):
    """Filter out empty/inverted intervals and sort by start."""
    return sorted((s, e) for s, e in intervals if s < e)


def merge(intervals):
    """Merge overlapping and touching intervals; return sorted list of tuples."""
    cleaned = _clean(intervals)
    if not cleaned:
        return []
    out = [list(cleaned[0])]
    for s, e in cleaned[1:]:
        if s <= out[-1][1]:
            if e > out[-1][1]:
                out[-1][1] = e
        else:
            out.append([s, e])
    return [(s, e) for s, e in out]


def free_gaps(intervals, window):
    """Maximal sub-ranges of [ws, we) not covered by any interval."""
    ws, we = window
    if ws >= we:
        return []
    merged = merge(intervals)
    gaps = []
    cur = ws
    for s, e in merged:
        if e <= cur:
            continue
        if s > cur:
            gaps.append((cur, s))
        cur = max(cur, e)
        if cur >= we:
            break
    if cur < we:
        gaps.append((cur, we))
    return gaps


def max_overlap(intervals):
    """Largest number of non-empty intervals sharing a common point."""
    events = []
    for s, e in intervals:
        if s < e:
            events.append((s, 1))
            events.append((e, -1))
    if not events:
        return 0
    # Half-open: at the same point, an end (-1) must sort before a start (+1).
    events.sort(key=lambda p: (p[0], p[1]))
    best = 0
    cur = 0
    for _, d in events:
        cur += d
        if cur > best:
            best = cur
    return best

"""LRU cache with per-entry time-to-live."""

import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        self.capacity = capacity
        self.clock = clock
        # key -> (value, expiry); expiry is None for non-expiring entries.
        # Dict order goes from least recently used to most recently used.
        self._entries = OrderedDict()

    def _purge_expired(self):
        now = self.clock()
        dead = [
            key
            for key, (value, expiry) in self._entries.items()
            if expiry is not None and now >= expiry
        ]
        for key in dead:
            del self._entries[key]
        return len(dead)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        expiry = None if ttl is None else self.clock() + ttl
        if key in self._entries:
            self._entries[key] = (value, expiry)
            self._entries.move_to_end(key)
        else:
            if len(self._entries) >= self.capacity:
                self._purge_expired()
                if len(self._entries) >= self.capacity:
                    self._entries.popitem(last=False)
            self._entries[key] = (value, expiry)
            self._entries.move_to_end(key)

    def get(self, key, default=None):
        entry = self._entries.get(key)
        if entry is None:
            return default
        value, expiry = entry
        if expiry is not None and self.clock() >= expiry:
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return value

    def __contains__(self, key):
        entry = self._entries.get(key)
        if entry is None:
            return False
        value, expiry = entry
        return expiry is None or self.clock() < expiry

    def __len__(self):
        self._purge_expired()
        return len(self._entries)

    def keys(self):
        self._purge_expired()
        return list(self._entries)

    def evict_expired(self):
        return self._purge_expired()

"""Recursive-descent evaluator for a small arithmetic expression language."""

import re

_TOKEN_RE = re.compile(
    r"\s*(?:(\d+\.\d*|\.\d+|\d+)|([A-Za-z_][A-Za-z_0-9]*)|(//|\*\*|[+\-*/%(),]))"
)

_FUNCTIONS = ("min", "max", "abs")


def _tokenize(text):
    tokens = []
    pos = 0
    size = len(text)
    while pos < size:
        match = _TOKEN_RE.match(text, pos)
        if match is None:
            raise ValueError("invalid character at position %d" % pos)
        pos = match.end()
        number, name, op = match.groups()
        if number is not None:
            tokens.append(("num", float(number) if "." in number else int(number)))
        elif name is not None:
            tokens.append(("name", name))
        else:
            tokens.append(("op", op))
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return (None, None)

    def advance(self):
        token = self.peek()
        self.pos += 1
        return token

    def parse(self):
        value = self.additive()
        kind, _ = self.peek()
        if kind is not None:
            raise ValueError("unexpected token after expression")
        return value

    def additive(self):
        left = self.multiplicative()
        while True:
            kind, op = self.peek()
            if kind == "op" and op in ("+", "-"):
                self.advance()
                right = self.multiplicative()
                left = left + right if op == "+" else left - right
            else:
                return left

    def multiplicative(self):
        left = self.unary()
        while True:
            kind, op = self.peek()
            if kind == "op" and op in ("*", "/", "//", "%"):
                self.advance()
                right = self.unary()
                if op == "*":
                    left = left * right
                elif op == "/":
                    left = left / right
                elif op == "//":
                    left = left // right
                else:
                    left = left % right
            else:
                return left

    def unary(self):
        kind, op = self.peek()
        if kind == "op" and op in ("+", "-"):
            self.advance()
            operand = self.unary()
            return -operand if op == "-" else +operand
        return self.power()

    def power(self):
        base = self.primary()
        kind, op = self.peek()
        if kind == "op" and op == "**":
            self.advance()
            # Right-associative; the exponent may carry its own unary sign.
            return base ** self.unary()
        return base

    def primary(self):
        kind, value = self.peek()
        if kind == "num":
            self.advance()
            return value
        if kind == "op" and value == "(":
            self.advance()
            inner = self.additive()
            kind2, op2 = self.peek()
            if kind2 != "op" or op2 != ")":
                raise ValueError("missing closing parenthesis")
            self.advance()
            return inner
        if kind == "name":
            self.advance()
            return self.call(value)
        raise ValueError("unexpected token")

    def call(self, name):
        kind, op = self.peek()
        if kind != "op" or op != "(":
            raise ValueError("expected '(' after %s" % name)
        self.advance()
        args = [self.additive()]
        while True:
            kind2, op2 = self.peek()
            if kind2 == "op" and op2 == ",":
                self.advance()
                args.append(self.additive())
            elif kind2 == "op" and op2 == ")":
                self.advance()
                break
            else:
                raise ValueError("malformed function call")
        if name == "abs":
            if len(args) != 1:
                raise ValueError("abs takes exactly one argument")
            return abs(args[0])
        if name in _FUNCTIONS:
            return min(args) if name == "min" else max(args)
        raise ValueError("unknown name %r" % name)


def evaluate(text):
    tokens = _tokenize(text)
    return _Parser(tokens).parse()

